import{_ as i,b as a,e,a7 as t}from"./chunks/framework.CFO60l-h.js";const m=JSON.parse('{"title":"笔试与面试","description":"RUC 新传保研 2024–2026 笔试/面试真题回忆与准备方法。","frontmatter":{"title":"笔试与面试","description":"RUC 新传保研 2024–2026 笔试/面试真题回忆与准备方法。","type":"baoyan-interview","tags":["保研","面试","笔试","真题"],"updated":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"baoyan/interview.md","filePath":"baoyan/interview.md","lastUpdated":null}'),o={name:"baoyan/interview.md"};function r(n,l,s,d,u,h){return a(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="笔试与面试" tabindex="-1">笔试与面试 <a class="header-anchor" href="#笔试与面试" aria-label="Permalink to &quot;笔试与面试&quot;">​</a></h1><blockquote><p>以下为同学回忆版，题面可能不完整；用于练手，不要当成原题押题。完整文件：<a href="/files/baoyan/ruc历年真题.docx">RUC 历年真题 DOCX</a>。</p></blockquote><h2 id="一、2026-年笔试-回忆" tabindex="-1">一、2026 年笔试（回忆） <a class="header-anchor" href="#一、2026-年笔试-回忆" aria-label="Permalink to &quot;一、2026 年笔试（回忆）&quot;">​</a></h2><ul><li>人民性</li><li>数字新闻（建议多看人大导师论文）</li><li>DeepSeek 对新闻业的影响</li><li>算法时代的新闻价值发生了怎样的变化</li><li>音乐怎么被传播学运用</li><li>用传播学理论解释 China Travel</li></ul><h2 id="二、2025-年笔试-回忆" tabindex="-1">二、2025 年笔试（回忆） <a class="header-anchor" href="#二、2025-年笔试-回忆" aria-label="Permalink to &quot;二、2025 年笔试（回忆）&quot;">​</a></h2><h3 id="学硕方向" tabindex="-1">学硕方向 <a class="header-anchor" href="#学硕方向" aria-label="Permalink to &quot;学硕方向&quot;">​</a></h3><ol><li>简答：舆情与舆论的区别（30 分）</li><li>论述：人工智能的概念及其对新闻业的影响（70 分）</li><li>论述：马克思主义新闻观的原则及在当下的实践路径（30 分）</li><li>英文题</li></ol><h3 id="普通专硕方向" tabindex="-1">普通专硕方向 <a class="header-anchor" href="#普通专硕方向" aria-label="Permalink to &quot;普通专硕方向&quot;">​</a></h3><ol><li>用户数据（点赞、评论、浏览量）是否构成新闻价值？如果是，属于何种新闻价值？如果不是，为什么？（30 分）</li><li>如何理解“党管媒体”在新媒体时代的体现？（70 分）</li><li>谈谈人机传播的概念，及其对新闻传播理论与实践的影响（需结合实例）。（30 分）</li><li>How do web influencers affect public opinion?（70 分）</li></ol><h2 id="三、2026-年面试-回忆" tabindex="-1">三、2026 年面试（回忆） <a class="header-anchor" href="#三、2026-年面试-回忆" aria-label="Permalink to &quot;三、2026 年面试（回忆）&quot;">​</a></h2><p><strong>中文</strong>：</p><ul><li>沉默的螺旋</li><li>移动端新闻 APP 对新闻消费的影响</li><li>老师会顺着你感兴趣的研究继续追问，包括研究缺陷</li><li>你未来期待的研究方向</li></ul><p><strong>英文</strong>：</p><ul><li>社交媒体对广告的影响</li><li>Fake news 如何摧毁社会信任</li></ul><blockquote><p>英文面难度大约相当于雅思口语 Part 3；会给 30 分钟思考时间，可在纸上做简要记录。</p></blockquote><h2 id="四、2025-年面试-回忆" tabindex="-1">四、2025 年面试（回忆） <a class="header-anchor" href="#四、2025-年面试-回忆" aria-label="Permalink to &quot;四、2025 年面试（回忆）&quot;">​</a></h2><ol><li>数字新闻业中的新闻价值有何新特征？</li><li>VR 技术对新闻业产生了哪些影响？</li><li>你还报名了哪些学校？如果均获得录取，将如何选择？</li><li>请简要介绍你的论文（是否独立完成？提交的是长摘要还是全文？）。</li></ol><h2 id="五、2024-年面试-回忆-节选" tabindex="-1">五、2024 年面试（回忆，节选） <a class="header-anchor" href="#五、2024-年面试-回忆-节选" aria-label="Permalink to &quot;五、2024 年面试（回忆，节选）&quot;">​</a></h2><details><summary>中文题（点击展开）</summary><ul><li>谈谈液态真实</li><li>中国国际新闻不同发展阶段以及对应的相关理论（国新）</li><li>异步传播媒介（国新）</li><li>好的对外传播案例（国新）</li><li>新媒体时代下新闻工作者的核心价值有哪些？（国新）</li><li>媒体在公共外交中发挥的作用？（国新）</li><li>民粹主义对国际化的内在影响？</li><li>网缘政治的理解</li><li>对适老化改造的理解</li><li>如何看待信息疫情（不足焦虑和过载）</li><li>对整合营销传播的理解</li><li>如何进行网络生态治理</li><li>什么是液态新闻</li><li>广告的社会效果</li><li>人工智能对国际新闻的影响</li><li>如何进行深度媒介化</li><li>请谈谈你对算法在新闻传播领域应用的看法？</li><li>请说一个你认为中国在国际上做很成功的广告案例？</li><li>请谈谈你对“电子斋戒”的认识？</li><li>你认为两级传播在社区中发挥了怎样的作用？</li></ul></details><details><summary>英文题（点击展开）</summary><ul><li>社交媒体的英文翻译</li><li>你有几段实习经历，从中学到了什么</li><li>介绍新媒体时代新闻业的创新</li><li>介绍计划行为理论</li><li>介绍实验法</li><li>分析淄博走红现象</li><li>介绍本科学校</li><li>介绍你获取新闻的方式</li><li>Please introduce a foreign media.</li><li>Please introduce a research method.</li><li>How to improve team efficiency?</li><li>How do you understand mainstream media?（国新）</li><li>How does international news impact cross-cultural communication and the stereotype or bias?（国新）</li><li>关于如何报道“一带一路”峰会给出一些建议？（国新）</li></ul></details><h2 id="六、怎么准备" tabindex="-1">六、怎么准备 <a class="header-anchor" href="#六、怎么准备" aria-label="Permalink to &quot;六、怎么准备&quot;">​</a></h2><h3 id="笔试" tabindex="-1">笔试 <a class="header-anchor" href="#笔试" aria-label="Permalink to &quot;笔试&quot;">​</a></h3><ul><li>建一个“理论—概念—案例”三列笔记：每个理论配 1 个近两年案例。</li><li>每周 1 篇限时论述（60–90 分钟），练“总—分—总”结构。</li><li>关注人大新闻学院导师近两年的论文/讲话，尤其是数字新闻、国际传播、算法/AI。</li><li>英文题准备 3 个万能框架：定义—影响—对策；案例—理论—评价；比较—原因—启示。</li></ul><h3 id="面试" tabindex="-1">面试 <a class="header-anchor" href="#面试" aria-label="Permalink to &quot;面试&quot;">​</a></h3><ul><li>1 分钟/3 分钟中英文自我介绍。</li><li>3 个“可讲的故事”：科研、实习、团队冲突。</li><li>2 个研究/作品，能讲清问题—方法—结果—反思。</li><li>1 个近期案例（国际新闻/传播/平台治理）。</li><li>准备“为什么选我们”“你还报了哪些”“如果没录取怎么办”。</li><li>模拟面试：录音/录像，每次只改 1 个问题。</li></ul><h3 id="国新方向额外准备" tabindex="-1">国新方向额外准备 <a class="header-anchor" href="#国新方向额外准备" aria-label="Permalink to &quot;国新方向额外准备&quot;">​</a></h3><ul><li>用英文讲一个中国国际传播案例，并能回应“宣传味太重”的质疑。</li><li>准备“你如何看待西方媒体对中国的报道”这类问题，避免空泛。</li><li>熟悉 2–3 个国际媒体/平台（BBC、Reuters、CNN、TikTok 等）的定位与争议。</li></ul><div class="tip custom-block"><p class="custom-block-title">真题怎么用</p><p>先限时写，再对照专题模板补框架；不要一上来背答案。面试题用来练“30 秒开口”的能力。</p></div>',28)])])}const b=i(o,[["render",r]]);export{m as __pageData,b as default};
